import {$,esc,icon,mount,heading,empty,field,back,accordion,busy,toast,confirmDialog,mapPreview,errorMessage} from '../ui.js';
import {getEvent,queryEventRows,allRows,insertRow,updateRow,deleteRow,signedUrls,uploadImage,locked,deadline,rpc,api} from '../data.js';
import {dateLabel} from './pages.js';
export async function renderWorkspace(root,user){const id=new URLSearchParams(location.search).get('id');if(!id){location.replace('events.html');return}let event,goals,tasks,notes,schedule,reminders,photos,sessions,interval;let openIds=new Set(['goals']);
async function load(){event=await getEvent(id,user);if(!event){mount(root,empty('This moment isn’t here.','It may have been deleted.','events.html','View events'));return}const result=await Promise.all(['goals','tasks','notes','schedule_items','reminders','event_memory_photos'].map(t=>queryEventRows(t,id)));[goals,tasks,notes,schedule,reminders,photos]=result;sessions=await allRows('task_sessions',q=>q.eq('user_id',user.id).order('created_at'));render()}
const run=fn=>busy(null,async()=>{openIds=new Set([...root.querySelectorAll('details[open]')].map(d=>d.id));await fn();await load()});
function taskHTML(task){const session=sessions.filter(s=>s.task_id===task.id).at(-1);const expired=session?.status==='expired';const canEdit=!locked(event);return `<div class="item ${task.completed?'done':''} ${!task.completed&&(expired||!canEdit)?'overdue':''}"><button class="check ${task.completed?'done':''}" data-check="${task.id}" aria-label="${task.completed?'Mark incomplete':'Complete'}: ${esc(task.title)}" aria-pressed="${task.completed}" ${!canEdit?'disabled':''}>${task.completed?icon('check'):''}</button><div class="grow"><p class="item-title">${esc(task.title)}</p>${!task.completed&&task.duration_seconds?`<small data-clock="${task.id}">${expired?'Incomplete · timer ended':session?esc(session.status):`${Math.round(task.duration_seconds/60)} minute timer`}</small><div class="row wrap">${canEdit?(session&&['running','paused'].includes(session.status)?`<button class="text-btn" data-timer="${session.status==='running'?'pause':'resume'}" data-id="${task.id}">${session.status==='running'?'Pause':'Resume'}</button><button class="text-btn" data-timer="stop" data-id="${task.id}">Stop</button>`:`<button class="text-btn" data-timer="${expired?'extend':'start'}" data-id="${task.id}">${expired?'Extend timer':'Start timer'}</button>`):''}</div>`:''}</div>${canEdit?`<button class="text-btn danger" data-delete-task="${task.id}" aria-label="Delete ${esc(task.title)}">Remove</button>`:''}</div>`}
function render(){clearInterval(interval);const past=event.status==='past',canEdit=!locked(event);const complete=tasks.filter(t=>t.completed).length;const percent=tasks.length?Math.round(complete/tasks.length*100):0;mount(root,back('events.html')+heading(past?'REMEMBER':'PLAN · LIVE',event.title,`${dateLabel(event.date)}${event.time?' · '+event.time.slice(0,5):''} · ${event.timezone}`)+`<section class="glass pad"><div class="row between"><div><span class="eyebrow">${past?'A MOMENT LIVED':'YOUR PREPARATION'}</span><h2>${complete} of ${tasks.length} tasks</h2></div><div class="ring" style="--progress:${percent}"><span>${percent}%</span></div></div><div class="progress"><span style="width:${percent}%"></span></div><p class="deadline section">${past?'Your preparation is saved as it was.':canEdit?`Preparation closes ${esc(new Date(deadline(event)).toLocaleString(undefined,{timeZone:event.timezone}))} (${esc(event.timezone)}).`:'Preparation has closed. Unfinished tasks remain incomplete.'}</p><div class="event-tools">${past?`<a class="btn primary" href="create.html?source=${event.id}">Do it again next year ${icon('arrow')}</a>`:`<button class="btn primary" id="completeEvent">${icon('check')}Complete event</button>`}<button class="btn danger" id="deleteEvent">Delete event</button></div></section>`+accordion('goals','Goals & tasks',`${goals.map(g=>{const rows=tasks.filter(t=>t.goal_id===g.id);return `<details class="group-card" open><summary><span class="row"><span class="goal-icon">${icon('goal')}</span>${esc(g.content)}</span><span class="badge ${rows.length&&rows.every(t=>t.completed)?'green':''}">${rows.filter(t=>t.completed).length}/${rows.length}</span></summary>${rows.map(taskHTML).join('')||'<p class="goal-empty">Add tasks to begin.</p>'}${canEdit?`<div class="row between"><button class="text-btn" data-add-task="${g.id}">+ Add task</button><button class="text-btn danger" data-delete-goal="${g.id}">Remove goal</button></div>`:''}</details>`}).join('')}<h3 class="section">Independent tasks</h3>${tasks.filter(t=>!t.goal_id).map(taskHTML).join('')||'<p class="goal-empty">Small steps belong here, too.</p>'}${canEdit?`<div class="row wrap"><button class="btn sm" data-add-task="">${icon('plus')}Add task</button><button class="btn sm" id="addGoal">${icon('goal')}Add goal</button></div>`:''}`,'goal',openIds.has('goals'))+accordion('notes','Notes',`${notes.map(n=>`<div class="item"><p class="note-content grow">${esc(n.content)}</p>${!past?`<button class="text-btn" data-edit-note="${n.id}">Edit</button><button class="text-btn danger" data-delete-note="${n.id}">Remove</button>`:''}</div>`).join('')||'<p class="goal-empty">Ideas, details and little reminders.</p>'}${!past?'<button class="btn sm" id="addNote">Add note</button>':''}`,'notes',openIds.has('notes'))+accordion('schedule','Schedule',`${schedule.sort((a,b)=>Date.parse(a.start_time)-Date.parse(b.start_time)).map(s=>`<div class="item"><div class="grow"><h3>${esc(s.title)}</h3><small>${esc(new Date(s.start_time).toLocaleString(undefined,{timeZone:event.timezone}))}</small></div>${!past?`<button class="text-btn danger" data-delete-schedule="${s.id}">Remove</button>`:''}</div>`).join('')||'<p class="goal-empty">A little structure for your moment.</p>'}${!past?'<button class="btn sm" id="addSchedule">Add schedule item</button>':''}`,'calendar',openIds.has('schedule'))+accordion('location','Location & details',`<p class="note-content">${esc(event.location||'No location set.')}</p>${mapPreview(event.place)}${event.location?`<div class="row wrap section">${[['driving','Drive'],['walking','Walk'],['transit','Transit']].map(([mode,label])=>`<a class="btn sm" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(event.place?`${event.place.lat},${event.place.lon}`:event.location)}&travelmode=${mode}">${icon('pin')}${label}</a>`).join('')}</div>`:''}${!past?`<div class="row wrap section"><button class="btn sm" id="editLocation">Edit location</button>${canEdit?'<button class="btn sm" id="editTime">Change start time</button>':''}</div>`:''}`,'pin',openIds.has('location'))+(!past?accordion('reminders','Reminders',`${reminders.map(r=>`<div class="item"><div class="grow"><h3>${esc(r.title)}</h3><small>${esc(new Date(r.remind_at).toLocaleString())} · ${esc(r.status)}</small></div>${!r.automatic_key?`<button class="text-btn danger" data-delete-reminder="${r.id}">Remove</button>`:''}</div>`).join('')}<button class="btn sm" id="addReminder">Add reminder</button>`,'bell',openIds.has('reminders')):accordion('memories','Your memories',`<label>Your reflection<textarea id="reflection" maxlength="10000" placeholder="How did it feel? What will you remember?">${esc(event.reflection)}</textarea></label><button class="btn primary section" id="saveReflection">Save reflection</button><div class="memory-grid section" id="photos"></div>${field('Add a memory','photo','file','','accept="image/jpeg,image/png,image/webp"')}<small>Keep the moments that matter. Up to 8 MB per photo.</small>`,'photo',true)));
root.querySelectorAll('[data-check]').forEach(b=>b.onclick=run(async()=>{const task=tasks.find(t=>t.id===b.dataset.check);await updateRow('tasks',task.id,{completed:!task.completed})}));root.querySelectorAll('[data-add-task]').forEach(b=>b.onclick=()=>addTask(b.dataset.addTask||null));root.querySelectorAll('[data-delete-task]').forEach(b=>b.onclick=run(async()=>{if(await confirmDialog('Remove task?','This task and its timer will be deleted.','Remove'))await deleteRow('tasks',b.dataset.deleteTask)}));root.querySelectorAll('[data-delete-goal]').forEach(b=>b.onclick=run(async()=>{if(await confirmDialog('Remove goal and tasks?','Every task in this goal will also be deleted.','Remove goal'))await deleteRow('goals',b.dataset.deleteGoal)}));if($('#addGoal'))$('#addGoal').onclick=()=>formDialog('A goal worth working towards.',field('Goal','content','text','','required maxlength="300"'),async f=>insertRow('goals',{event_id:id,content:f.content.value.trim()}));if($('#addNote'))$('#addNote').onclick=()=>editNote();root.querySelectorAll('[data-edit-note]').forEach(b=>b.onclick=()=>editNote(notes.find(n=>n.id===b.dataset.editNote)));for(const kind of ['note','schedule','reminder'])root.querySelectorAll(`[data-delete-${kind}]`).forEach(b=>b.onclick=run(()=>deleteRow({note:'notes',schedule:'schedule_items',reminder:'reminders'}[kind],b.dataset[`delete${kind[0].toUpperCase()+kind.slice(1)}`])));
if($('#addSchedule'))$('#addSchedule').onclick=()=>formDialog('A little structure.',field('Title','title','text','','required maxlength="200"')+field('Date','date','date',event.date,`required max="${event.date}"`)+field('Start time','time','time','','required'),async f=>insertRow('schedule_items',{event_id:id,title:f.title.value.trim(),start_time:new Date(window.PreludeHomeData.eventStart({date:f.date.value,time:f.time.value,timezone:event.timezone})).toISOString()}));if($('#addReminder'))$('#addReminder').onclick=()=>formDialog('A gentle nudge.',field('Reminder','title','text','','required maxlength="200"')+field('Remind me at','time','datetime-local','','required'),async f=>{const remind_at=new Date(f.time.value).toISOString();if(Date.parse(remind_at)<=Date.now())throw {friendly:'Choose a reminder time in the future.'};return insertRow('reminders',{event_id:id,title:f.title.value.trim(),remind_at})});if($('#editTime'))$('#editTime').onclick=()=>formDialog('Change your start time.',field('Time','time','time',event.time||''),f=>updateRow('events',id,{time:f.time.value||null}));if($('#editLocation'))$('#editLocation').onclick=()=>locationDialog();
$('#deleteEvent').onclick=run(async()=>{if(!(await confirmDialog('Delete this event?','All goals, tasks, notes and memories will be permanently deleted.','Delete event')))return;await deleteRow('events',id);location.replace('events.html')});if($('#completeEvent'))$('#completeEvent').onclick=run(async()=>{const localDate=new Intl.DateTimeFormat('en-CA',{timeZone:event.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(localDate<event.date)throw {friendly:'You can complete this event on its event day.'};if(await confirmDialog('Complete this moment?',tasks.some(t=>!t.completed)?'Unfinished tasks will remain incomplete. Your preparation will become read-only.':'Your preparation will be saved. You can add photos and reflections afterwards.','Complete event'))await updateRow('events',id,{status:'past'})});
root.querySelectorAll('[data-timer]').forEach(b=>b.onclick=run(async()=>{if(b.dataset.timer==='extend'){timerExtension(b.dataset.id);return}await rpc('prelude_timer',{p_task:b.dataset.id,p_action:b.dataset.timer})}));
if(past){$('#saveReflection').onclick=busy($('#saveReflection'),async()=>{event=await updateRow('events',id,{reflection:$('#reflection').value});toast('Reflection saved.')});$('[name=photo]').onchange=run(async()=>{const file=$('[name=photo]').files[0];if(!file)return;const storage_path=await uploadImage(user,'memory-photos',file);await insertRow('event_memory_photos',{event_id:id,storage_path})});signedUrls('memory-photos',photos.map(p=>p.storage_path)).then(urls=>{if(!$('#photos'))return;$('#photos').innerHTML=photos.map(p=>`<div class="memory-photo">${urls[p.storage_path]?`<img src="${esc(urls[p.storage_path])}" alt="Memory from ${esc(event.title)}">`:'<p>Photo unavailable</p>'}<button class="icon-btn" data-photo="${p.id}" aria-label="Delete memory photo">×</button></div>`).join('');root.querySelectorAll('[data-photo]').forEach(b=>b.onclick=run(async()=>{if(await confirmDialog('Delete photo?','This photo will be removed from your memories.','Delete')){const photo=photos.find(p=>p.id===b.dataset.photo);await deleteRow('event_memory_photos',photo.id);await supabaseClient.storage.from('memory-photos').remove([photo.storage_path])}}))})}
const tick=()=>{if(!past&&!canEdit)return;if(canEdit&&Date.now()>=deadline(event)){render();return}for(const task of tasks){const el=$(`[data-clock="${task.id}"]`);if(!el)continue;const s=sessions.filter(s=>s.task_id===task.id).at(-1);if(!s)continue;const seconds=s.status==='running'?Math.max(0,Math.ceil((Date.parse(s.ends_at)-Date.now())/1000)):s.remaining_seconds;if(s.status==='running'&&seconds===0){el.textContent='Incomplete · timer ended';el.closest('.item').classList.add('overdue');rpc('prelude_sync_events').then(()=>load()).catch(()=>{});continue}if(['running','paused','stopped'].includes(s.status))el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')} · ${s.status}`}};tick();interval=setInterval(tick,1000)}
function formDialog(title,fields,save,bind){const dialog=document.createElement('dialog');dialog.className='modal';dialog.innerHTML=`<form class="stack"><h2>${esc(title)}</h2>${fields}<div class="row"><button class="btn" type="button" data-cancel>Cancel</button><button class="btn primary" type="submit">Save</button></div></form>`;document.body.append(dialog);$('[data-cancel]',dialog).onclick=()=>{dialog.close();dialog.remove()};$('form',dialog).onsubmit=busy($('[type=submit]',dialog),async()=>{await save($('form',dialog));dialog.close();dialog.remove();await load();toast('Saved.')});dialog.addEventListener('close',()=>dialog.remove());bind?.(dialog);dialog.showModal()}
function addTask(goal_id){formDialog('A small step forward.',field('Task','title','text','','required maxlength="300"')+field('Timer duration · minutes, optional','minutes','number','','min="1" max="1440" step="1"'),f=>insertRow('tasks',{event_id:id,goal_id,title:f.title.value.trim(),completed:false,duration_seconds:f.minutes.value?Number(f.minutes.value)*60:null}))}
function editNote(note){formDialog(note?'Edit note.':'Something to remember.',`<label>Note<textarea name="content" required maxlength="10000">${esc(note?.content||'')}</textarea></label>`,f=>note?updateRow('notes',note.id,{content:f.content.value.trim()}):insertRow('notes',{event_id:id,content:f.content.value.trim()}))}
function timerExtension(task){formDialog('A little more time.',`<label>Extend by<select name="minutes"><option value="5">5 minutes</option><option value="10">10 minutes</option><option value="15">15 minutes</option><option value="custom">Custom</option></select></label>${field('Custom minutes','custom','number','','min="1" max="1440"')}`,f=>{const seconds=Number(f.minutes.value==='custom'?f.custom.value:f.minutes.value)*60;if(!seconds||seconds>86400)throw {friendly:'Choose between 1 and 1440 minutes.'};return rpc('prelude_timer',{p_task:task,p_action:'extend',p_seconds:seconds})})}
function locationDialog(){let place=event.place;formDialog('Where will it happen?',field('Location','location','text',event.location||'','maxlength="300"')+'<button class="btn sm" type="button" data-search>Find on map</button><div data-places></div><div data-map>'+mapPreview(place)+'</div>',f=>updateRow('events',id,{location:f.location.value.trim(),place:place&&place.label===f.location.value.trim()?place:null}),dialog=>{$('[data-search]',dialog).onclick=busy($('[data-search]',dialog),async()=>{const q=$('[name=location]',dialog).value.trim();if(q.length<3)throw {friendly:'Enter at least three characters.'};const result=await api(`/api/places?q=${encodeURIComponent(q)}`,{authenticated:true});$('[data-places]',dialog).innerHTML=result.places.map((p,i)=>`<button class="btn full place-result" type="button" data-place="${i}">${esc(p.label)}</button>`).join('')||'<small>No places found.</small>';dialog.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{place=result.places[Number(b.dataset.place)];$('[name=location]',dialog).value=place.label;$('[data-map]',dialog).innerHTML=mapPreview(place);$('[data-places]',dialog).innerHTML=''})})})}
await load();window.addEventListener('pagehide',()=>clearInterval(interval),{once:true})}
